-- ================================================================
-- Sprint 14 Fix: Add Microsoft Fabric Medallion Cartridge Prompts
-- Date: 2026-02-20
-- ================================================================
-- Problem: Projects with target_tech='fabric' cannot find cartridge prompts
--          for Bronze, Silver, and Gold layers (404 errors)
-- Solution: Insert 3 new cartridge prompts for Microsoft Fabric Medallion layers
--           (adapted from Databricks cartridges since Fabric uses PySpark + Delta Lake)
-- ================================================================

-- ================================================================
-- 1. BRONZE LAYER CARTRIDGE
-- ================================================================
INSERT INTO public.utm_prompts (
    prompt_id,
    content,
    is_active,
    agent_id,
    tech_stack,
    pattern_type,
    metadata,
    created_at,
    updated_at
) VALUES (
    'cartridge_fabric_bronze',
    E'# Microsoft Fabric PySpark Bronze Layer Cartridge Rules\n\n## 🎯 CRITICAL COMPLIANCE REQUIREMENTS (Zero-Hardcode Policy)\n\n### 1. MANDATORY L2L MODERNIZATION TRACE HEADER\n```python\n# ================================================================\n# L2L MODERNIZATION TRACE: Bronze Layer - {{asset_name}}\n# ================================================================\n# Source Asset: {{source_asset_name}}\n# Source Technology: {{source_tech}}\n# Target Platform: Microsoft Fabric (Lakehouse + PySpark + Delta Lake)\n# Medallion Layer: Bronze\n# Component Type: Data Pipeline\n# Business Entity: {{business_entity}}\n# Load Strategy: {{load_strategy}}\n# Generated At: {{timestamp}}\n# Generated By: L2L Agent-C (Cartridge: FabricBronze v4.0)\n# ================================================================\n```\n\n### 2. ZERO-HARDCODE CONFIGURATION\n**❌ FORBIDDEN: Hardcoded values anywhere in code**\n- NO hardcoded paths: `/lakehouse/default/Tables/bronze_*`\n- NO example credentials: `<JDBC_URL>`, `<USER>`, `<PASSWORD>`\n- NO sample configs in `main()` functions\n- NO static connection strings\n\n**✅ REQUIRED: All paths and configs from orchestrator context**\n```python\ndef execute_task(spark, config):\n    # Extract ALL values from config dictionary\n    bronze_path = config[''bronze_path'']\n    workspace = config.get(''workspace_name'', ''default'')\n    lakehouse = config.get(''lakehouse_name'', ''main'')\n    jdbc_url = config[''jdbc_url'']  # Injected by orchestrator\n    jdbc_user = config[''jdbc_user'']  # Injected by orchestrator\n    jdbc_password = config[''jdbc_password'']  # Injected by orchestrator\n```\n\n### 3. PARAMETERIZED EXTRACTION (Required)\n**✅ REQUIRED: Parameterized extraction using config**\n```python\n# Extract parameters from config\nif config.get(''load_mode'') == ''incremental'':\n    watermark_col = config[''watermark_column'']\n    last_watermark = config.get(''last_watermark_value'')\n    \n    query = f"""\n        SELECT * FROM {config[''source_table'']}\n        WHERE {watermark_col} > ''{last_watermark}''\n    """\n    df = spark.read.jdbc(url=jdbc_url, table=f"({query}) AS incremental_data", properties={...})\nelse:\n    df = spark.read.jdbc(url=jdbc_url, table=config[''source_table''], properties={...})\n```\n\n### 4. BRONZE LAYER SPECIFIC REQUIREMENTS\n**Medallion Columns (Automatically Added):**\n```python\n# Add Bronze layer metadata columns\ndf_bronze = df \\\n    .withColumn("_ingestion_timestamp", F.current_timestamp()) \\\n    .withColumn("_source_file", F.lit(config.get(''source_file'', ''N/A''))) \\\n    .withColumn("_record_hash", F.sha2(F.concat_ws("||", *df.columns), 256))\n```\n\n**Write Pattern:**\n```python\n# Bronze: Always append (never overwrite)\ndf_bronze.write \\\n    .format("delta") \\\n    .mode("append") \\\n    .option("mergeSchema", "true") \\\n    .save(config[''bronze_path''])\n```\n\n### 5. TYPE CASTING FROM METADATA (Sprint 10 Compliance)\n```python\n# Apply type casting from metadata (utm_asset_columns)\nfrom pyspark.sql.types import *\n\ndef _parse_data_type(dtype_str):\n    dtype_map = {\n        ''STRING'': StringType(), ''INT'': IntegerType(),\n        ''BIGINT'': LongType(), ''DOUBLE'': DoubleType(),\n        ''DECIMAL'': DecimalType(38, 10),\n        ''DATE'': DateType(), ''TIMESTAMP'': TimestampType(),\n        ''BOOLEAN'': BooleanType()\n    }\n    return dtype_map.get(str(dtype_str).upper(), StringType())\n\n# Cast columns\ndf_typed = df.select([\n    F.col(col[''name'']).cast(_parse_data_type(col[''data_type''])).alias(col[''name''])\n    for col in config.get(''columns'', [])\n])\n```\n\n### 6. ROW COUNT LOGGING (Required)\n```python\nimport logging\nlogger = logging.getLogger(__name__)\n\n# Log row counts at each stage\nlogger.info(f"[EXTRACT] Source rows: {df.count()}")\nlogger.info(f"[TRANSFORM] Typed rows: {df_typed.count()}")\nlogger.info(f"[LOAD] Bronze rows written: {df_bronze.count()}")\n```\n\n## 🎯 VALIDATION CHECKLIST (Agent F Criteria)\n- ✅ Header: L2L MODERNIZATION TRACE with all fields\n- ✅ No hardcoded paths/credentials\n- ✅ Function signature: `execute_task(spark, config)`\n- ✅ Type casting from metadata (utm_asset_columns)\n- ✅ Bronze metadata columns: `_ingestion_timestamp`, `_source_file`, `_record_hash`\n- ✅ Write mode: `append` (never overwrite)\n- ✅ Row count logging at each stage\n- ✅ Incremental logic uses config parameters',
    true,
    'agent-c',
    'fabric',
    'bronze',
    '{"description": "Microsoft Fabric Bronze Layer cartridge (raw data ingestion with Medallion pattern)", "version": "4.0", "created_by": "sprint_14_fabric_fix", "adapted_from": "cartridge_databricks_bronze"}'::jsonb,
    NOW(),
    NOW()
)
ON CONFLICT (prompt_id) DO UPDATE SET
    content = EXCLUDED.content,
    is_active = EXCLUDED.is_active,
    agent_id = EXCLUDED.agent_id,
    tech_stack = EXCLUDED.tech_stack,
    pattern_type = EXCLUDED.pattern_type,
    metadata = EXCLUDED.metadata,
    updated_at = NOW();

-- ================================================================
-- 2. SILVER LAYER CARTRIDGE
-- ================================================================
INSERT INTO public.utm_prompts (
    prompt_id,
    content,
    is_active,
    agent_id,
    tech_stack,
    pattern_type,
    metadata,
    created_at,
    updated_at
) VALUES (
    'cartridge_fabric_silver',
    E'# Microsoft Fabric PySpark Silver Layer Cartridge Rules\n\n## 🎯 CRITICAL COMPLIANCE REQUIREMENTS (Zero-Hardcode Policy)\n\n### 1. MANDATORY L2L MODERNIZATION TRACE HEADER\n```python\n# ================================================================\n# L2L MODERNIZATION TRACE: Silver Layer - {{asset_name}}\n# ================================================================\n# Source Asset: {{source_asset_name}}\n# Source Technology: {{source_tech}}\n# Target Platform: Microsoft Fabric (Lakehouse + PySpark + Delta Lake)\n# Medallion Layer: Silver\n# Component Type: Data Pipeline\n# Business Entity: {{business_entity}}\n# Load Strategy: {{load_strategy}}\n# Generated At: {{timestamp}}\n# Generated By: L2L Agent-C (Cartridge: FabricSilver v4.0)\n# ================================================================\n```\n\n### 2. SILVER LAYER CHARACTERISTICS\n**Purpose:** Cleansed, deduplicated, and conformed data\n\n**Key Features:**\n- Read from Bronze layer (Delta Lake)\n- Data quality checks and cleansing\n- Deduplication using business keys\n- Standardized naming conventions\n- MERGE operations for SCD Type 1/2\n\n### 3. READ FROM BRONZE\n```python\n# Read from Bronze layer\nbronze_path = config[''bronze_path'']\ndf_bronze = spark.read.format("delta").load(bronze_path)\n\n# Apply incremental filter if needed\nif config.get(''load_mode'') == ''incremental'':\n    last_timestamp = config[''last_run_timestamp'']\n    df_bronze = df_bronze.filter(F.col("_ingestion_timestamp") > last_timestamp)\n```\n\n### 4. DATA QUALITY CHECKS\n```python\n# Remove nulls in critical columns\ndf_cleaned = df_bronze.dropna(subset=config.get(''critical_columns'', []))\n\n# Standardize string columns\ndf_cleaned = df_cleaned \\\n    .withColumn("customer_name", F.trim(F.upper(F.col("customer_name")))) \\\n    .withColumn("email", F.lower(F.trim(F.col("email"))))\n\n# Log data quality metrics\ninitial_count = df_bronze.count()\nfinal_count = df_cleaned.count()\nrejected_count = initial_count - final_count\nlogger.info(f"[DQ] Initial: {initial_count}, Cleaned: {final_count}, Rejected: {rejected_count}")\n```\n\n### 5. DEDUPLICATION (Business Key)\n```python\n# Deduplicate using business key from config\nbusiness_keys = config.get(''business_keys'', [])\n\nif business_keys:\n    window_spec = Window.partitionBy(*business_keys).orderBy(F.col("_ingestion_timestamp").desc())\n    df_dedup = df_cleaned \\\n        .withColumn("row_num", F.row_number().over(window_spec)) \\\n        .filter(F.col("row_num") == 1) \\\n        .drop("row_num")\nelse:\n    df_dedup = df_cleaned\n```\n\n### 6. MERGE INTO SILVER (SCD Type 1)\n```python\nfrom delta.tables import DeltaTable\n\nsilver_path = config[''silver_path'']\n\nif DeltaTable.isDeltaTable(spark, silver_path):\n    silver_table = DeltaTable.forPath(spark, silver_path)\n    \n    merge_condition = " AND ".join([f"target.{key} = source.{key}" for key in business_keys])\n    \n    silver_table.alias("target").merge(\n        df_silver.alias("source"),\n        merge_condition\n    ).whenMatchedUpdateAll() \\\n     .whenNotMatchedInsertAll() \\\n     .execute()\n    \n    logger.info(f"[MERGE] Silver merge completed")\nelse:\n    # First load - create table\n    df_silver.write.format("delta").mode("overwrite").save(silver_path)\n    logger.info(f"[CREATE] Silver table created with {df_silver.count()} rows")\n```\n\n### 7. SILVER METADATA COLUMNS\n```python\n# Add Silver layer metadata\ndf_silver = df_dedup \\\n    .withColumn("_processed_timestamp", F.current_timestamp()) \\\n    .withColumn("_silver_layer", F.lit("silver")) \\\n    .withColumn("_is_current", F.lit(True)) \\\n    .drop("_record_hash", "_source_file")  # Remove Bronze metadata\n```\n\n## 🎯 VALIDATION CHECKLIST (Agent F Criteria)\n- ✅ Header: L2L MODERNIZATION TRACE with Silver layer\n- ✅ Read from Bronze Delta table\n- ✅ Data quality checks implemented\n- ✅ Deduplication using business keys\n- ✅ MERGE operation for SCD Type 1\n- ✅ Silver metadata columns: `_processed_timestamp`, `_silver_layer`, `_is_current`\n- ✅ No hardcoded values\n- ✅ Row count logging',
    true,
    'agent-c',
    'fabric',
    'silver',
    '{"description": "Microsoft Fabric Silver Layer cartridge (cleaned and deduplicated data with Medallion pattern)", "version": "4.0", "created_by": "sprint_14_fabric_fix", "adapted_from": "cartridge_databricks_silver"}'::jsonb,
    NOW(),
    NOW()
)
