    updated_at = NOW();

-- ================================================================
-- 3. GOLD LAYER CARTRIDGE
-- ================================================================
INSERT INTO public.utm_prompts (
    prompt_id,
    content,
    is_active,
    agent_id,
    tech_stack,
    pattern_type,
    metadata,
    created_at,
    updated_at
) VALUES (
    'cartridge_fabric_gold',
    E'# Microsoft Fabric PySpark Gold Layer Cartridge Rules\n\n## 🎯 CRITICAL COMPLIANCE REQUIREMENTS (Zero-Hardcode Policy)\n\n### 1. MANDATORY L2L MODERNIZATION TRACE HEADER\n```python\n# ================================================================\n# L2L MODERNIZATION TRACE: Gold Layer - {{asset_name}}\n# ================================================================\n# Source Asset: {{source_asset_name}}\n# Source Technology: {{source_tech}}\n# Target Platform: Microsoft Fabric (Lakehouse + PySpark + Delta Lake)\n# Medallion Layer: Gold\n# Component Type: Data Pipeline\n# Business Entity: {{business_entity}}\n# Load Strategy: {{load_strategy}}\n# Generated At: {{timestamp}}\n# Generated By: L2L Agent-C (Cartridge: FabricGold v4.0)\n# ================================================================\n```\n\n### 2. GOLD LAYER CHARACTERISTICS\n**Purpose:** Business-ready, aggregated, and dimensionally modeled data\n\n**Key Features:**\n- Read from Silver layer(s)\n- Join multiple Silver tables\n- Business logic aggregations\n- Dimensional modeling (Facts/Dimensions)\n- Optimized for analytics and reporting\n\n### 3. READ FROM SILVER LAYER(S)\n```python\n# Read from Silver layer(s)\ndf_customers = spark.read.format("delta").load(config[''silver_customers_path''])\ndf_orders = spark.read.format("delta").load(config[''silver_orders_path''])\ndf_products = spark.read.format("delta").load(config[''silver_products_path''])\n```\n\n### 4. BUSINESS LOGIC TRANSFORMATIONS\n```python\n# Join Silver tables\ndf_gold = df_orders \\\n    .join(df_customers, df_orders.customer_id == df_customers.customer_id, "left") \\\n    .join(df_products, df_orders.product_id == df_products.product_id, "left")\n\n# Apply business logic\ndf_gold = df_gold \\\n    .withColumn("total_revenue", F.col("quantity") * F.col("unit_price")) \\\n    .withColumn("profit_margin", \n        (F.col("unit_price") - F.col("cost_price")) / F.col("unit_price") * 100\n    ) \\\n    .withColumn("sales_quarter", F.quarter(F.col("order_date"))) \\\n    .withColumn("customer_segment", \n        F.when(F.col("lifetime_value") > 10000, "Premium")\n         .when(F.col("lifetime_value") > 5000, "Standard")\n         .otherwise("Basic")\n    )\n```\n\n### 5. AGGREGATIONS (Fact Tables)\n```python\n# Create aggregated fact table\ndf_fact_sales = df_gold.groupBy(\n    "sales_quarter",\n    "customer_segment",\n    "product_category"\n).agg(\n    F.sum("total_revenue").alias("total_revenue"),\n    F.avg("profit_margin").alias("avg_profit_margin"),\n    F.count("order_id").alias("order_count"),\n    F.countDistinct("customer_id").alias("unique_customers")\n)\n\nlogger.info(f"[AGGREGATE] Fact table rows: {df_fact_sales.count()}")\n```\n\n### 6. DIMENSIONAL MODELING (SCD Type 2)\n```python\nfrom delta.tables import DeltaTable\n\ngold_path = config[''gold_path'']\n\nif DeltaTable.isDeltaTable(spark, gold_path):\n    gold_table = DeltaTable.forPath(spark, gold_path)\n    \n    # SCD Type 2: Track historical changes\n    merge_condition = "target.customer_id = source.customer_id AND target.is_current = TRUE"\n    \n    gold_table.alias("target").merge(\n        df_gold.alias("source"),\n        merge_condition\n    ).whenMatchedUpdate(\n        condition = "target.customer_name != source.customer_name OR target.email != source.email",\n        set = {\n            "is_current": "FALSE",\n            "end_date": "current_timestamp()"\n        }\n    ).whenNotMatchedInsert(\n        values = {\n            "customer_id": "source.customer_id",\n            "customer_name": "source.customer_name",\n            "email": "source.email",\n            "is_current": "TRUE",\n            "start_date": "current_timestamp()",\n            "end_date": "NULL"\n        }\n    ).execute()\n    \n    logger.info(f"[MERGE] Gold SCD Type 2 merge completed")\nelse:\n    # First load\n    df_gold \\\n        .withColumn("is_current", F.lit(True)) \\\n        .withColumn("start_date", F.current_timestamp()) \\\n        .withColumn("end_date", F.lit(None).cast("timestamp")) \\\n        .write.format("delta").mode("overwrite").save(gold_path)\n    \n    logger.info(f"[CREATE] Gold table created with {df_gold.count()} rows")\n```\n\n### 7. GOLD METADATA COLUMNS\n```python\n# Add Gold layer metadata\ndf_gold_final = df_gold \\\n    .withColumn("_gold_processed_timestamp", F.current_timestamp()) \\\n    .withColumn("_aggregation_level", F.lit(config.get(''aggregation_level'', ''detailed''))) \\\n    .withColumn("_last_refreshed", F.current_timestamp())\n```\n\n### 8. OPTIMIZATION (Gold Layer Specific)\n```python\n# Optimize Gold tables for analytics\nfrom delta.tables import DeltaTable\n\ngold_table = DeltaTable.forPath(spark, gold_path)\n\n# OPTIMIZE and Z-ORDER for query performance\ngold_table.optimize().executeZOrderBy(config.get(''zorder_columns'', [''customer_id'', ''order_date'']))\n\n# VACUUM old versions (optional, configured)\nif config.get(''enable_vacuum'', False):\n    retention_hours = config.get(''vacuum_retention_hours'', 168)  # 7 days default\n    gold_table.vacuum(retention_hours / 24)  # Convert to days\n\nlogger.info(f"[OPTIMIZE] Gold table optimized and z-ordered")\n```\n\n## 🎯 VALIDATION CHECKLIST (Agent F Criteria)\n- ✅ Header: L2L MODERNIZATION TRACE with Gold layer\n- ✅ Read from Silver Delta table(s)\n- ✅ Business logic transformations\n- ✅ Aggregations for fact tables\n- ✅ Dimensional modeling (SCD Type 2 if applicable)\n- ✅ MERGE operation with historical tracking\n- ✅ Gold metadata columns: `_gold_processed_timestamp`, `_aggregation_level`, `_last_refreshed`\n- ✅ Optimization: OPTIMIZE and Z-ORDER\n- ✅ No hardcoded values\n- ✅ Row count logging',
    true,
    'agent-c',
    'fabric',
    'gold',
    '{"description": "Microsoft Fabric Gold Layer cartridge (business-ready aggregated data with Medallion pattern)", "version": "4.0", "created_by": "sprint_14_fabric_fix", "adapted_from": "cartridge_databricks_gold"}'::jsonb,
    NOW(),
    NOW()
)
